// server/pi-extensions/permission-gate.ts
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { isToolCallEventType } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
  const DANGEROUS = /\b(rm\s+-rf|mkfs|dd\s+if=|>:?\s*\/dev\/|curl\s+.*\|\s*sh)\b/;

  pi.on("tool_call", async (event, ctx) => {
    if (event.toolName === "bash" && isToolCallEventType("bash", event)) {
      if (DANGEROUS.test(event.input.command)) {
        return { block: true, reason: "Dangerous command blocked by policy", terminate: true };
      }
    }

    // Optionally require approval for write/edit outside certain paths
    if (["write", "edit"].includes(event.toolName)) {
      const path = (event.input as { path: string }).path;
      if (!path.startsWith(ctx.cwd)) {
        return { block: true, reason: `Writes outside project root not allowed: ${path}` };
      }
    }
  });
}
```

