## Registering custom tools in pi

### Inline via SDK

```ts
import { defineTool, createAgentSession } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

const presentationUpdate = defineTool({
  name: "presentation_update",
  label: "Update Presentation",
  description: "Modify the live presentation. Use when the user asks to change layout, styling, or content of slides.",
  parameters: Type.Object({
    action: Type.StringEnum(["setPosition", "setSize", "setText", "setFillColor", "setFontSize", "applyGridLayout"]),
    targetIds: Type.Array(Type.String(), { description: "IDs of selected objects" }),
    args: Type.Record(Type.String(), Type.Unknown(), {
      description: "Action-specific parameters",
    }),
  }),
  execute: async (_toolCallId, params, _signal, _onUpdate, ctx) => {
    // Send to the presentation editor via your web layer
    const result = await presentationApi.update(params);
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      details: {},
    };
  },
});

const { session } = await createAgentSession({
  customTools: [presentationUpdate],
});
```

### Via an extension

Better for organizing multiple tools and reacting to editor events:

```ts
// .pi/extensions/presentation.ts or ~/.pi/agent/extensions/presentation.ts
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

export default function (pi: ExtensionAPI) {
  pi.registerTool({
    name: "presentation_update",
    label: "Update Presentation",
    description: "Modify the live presentation editor.",
    parameters: Type.Object({
      action: Type.String(),
      targetIds: Type.Array(Type.String()),
      args: Type.Record(Type.String(), Type.Unknown()),
    }),
    execute: async (_id, params, _signal, _onUpdate, ctx) => {
      // Call your presentation backend
      const result = await fetch("http://localhost:3001/api/presentation/update", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(params),
      }).then(r => r.json());

      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        details: result,
      };
    },
  });
}
```

