## Wiring it into the web harness

Your extension becomes the bridge between pi and your editor backend:

```ts
// server/pi-extensions/presentation-bridge.ts
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

const EDITOR_API = "http://localhost:3001/api/editor";

async function callEditor(method: string, body: unknown) {
  const res = await fetch(`${EDITOR_API}/${method}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  return res.json();
}

export default function (pi: ExtensionAPI) {
  pi.registerTool({
    name: "presentation_get_state",
    label: "Get Presentation State",
    description: "Get the current presentation state, including all objects and the current selection.",
    parameters: Type.Object({}),
    execute: async () => {
      const state = await callEditor("getState", {});
      return {
        content: [{ type: "text", text: JSON.stringify(state, null, 2) }],
        details: state,
      };
    },
  });

  pi.registerTool({
    name: "presentation_update",
    label: "Update Presentation",
    description: `Modify the live presentation. Use for layout, styling, and content changes.`,
    parameters: Type.Object({
      action: Type.StringEnum([
        "setPosition",
        "setSize",
        "setText",
        "setFillColor",
        "setFontSize",
        "applyGridLayout",
      ]),
      targetIds: Type.Array(Type.String(), { description: "IDs of objects to modify" }),
      args: Type.Record(Type.String(), Type.Unknown()),
    }),
    execute: async (_id, params) => {
      const result = await callEditor("update", params);
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        details: result,
      };
    },
  });

  pi.registerTool({
    name: "presentation_select_by_text",
    label: "Select by Text",
    description: "Return IDs of text boxes whose text contains the given string.",
    parameters: Type.Object({
      query: Type.String(),
      caseSensitive: Type.Optional(Type.Boolean()),
    }),
    execute: async (_id, params) => {
      const state = await callEditor("getState", {});
      const ids = state.objects
        .filter((o: any) => o.text?.toLowerCase().includes(params.query.toLowerCase()))
        .map((o: any) => o.id);
      return {
        content: [{ type: "text", text: `Matched IDs: ${ids.join(", ")}` }],
        details: { ids },
      };
    },
  });
}
```

